private static void OnSourceCardRemoved(PlayOrigin origin, CardModel removed)
	{
		if (origin.Card == removed)
		{
			ClearOrigin(origin);
		}
	}

private static void ClearOrigin(PlayOrigin origin)
	{
		if (_active == origin)
		{
			_active = null;
		}
		if (!origin.Closed)
		{
			origin.Closed = true;
			PendingOrigins.Remove(origin.Card);
			if (origin.SourceCardRemoved != null)
			{
				origin.SourcePile.CardRemoved -= origin.SourceCardRemoved;
			}
			origin.SourceCardRemoved = null;
		}
	}

public void Install()
	{
		if (<view>P.EnableCardInspect)
		{
			InstallCardInspection();
		}
		if (<view>P.EnableSortBar)
		{
			InstallToolbar();
		}
		if (<view>P.EnableUpgradePreviewToggle)
		{
			InstallUpgradeToggle();
		}
		<screen>P.Pile.ContentsChanged += RefreshCards;
